import React, { useState } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import Features from './components/Features';
import TradingStats from './components/TradingStats';
import './App.css';

function App() {
  const [walletAddress, setWalletAddress] = useState('');

  return (
    <div className="min-h-screen bg-mystery-dark">
      <Navbar walletAddress={walletAddress} setWalletAddress={setWalletAddress} />
      <Hero walletAddress={walletAddress} setWalletAddress={setWalletAddress} />
      <div className="bg-gradient-to-b from-[#0B041A] to-mystery-dark">
        <main className="container mx-auto px-4">
          <Features />
          <TradingStats />
        </main>
      </div>
    </div>
  );
}

export default App;
